USE CustDB
GO

UPDATE c 
SET username2 = NULL
FROM customer c (nolock) 
WHERE custid in (35653291,35710026,35710030,35721709,35721849,35721910,35721923,35721927,35726433,35726463,35738192,35738204,35738227,35738260,
35738279,35738397,35738446,35738449,35738502,35738504,35738552,35738604,35738623,35738633,35741999,35742003,35742190,35743029,35743354,35743362,
35743989,35744013,35744036,35745681,35745719,35746052,35746075)
	AND c.roleid = 1 AND c.currency = 20

SELECT site,currency,srecommend,  username, username2 
FROM vw_customer c (nolock) 
WHERE custid in (35653291,35710026,35710030,35721709,35721849,35721910,35721923,35721927,35726433,35726463,35738192,35738204,35738227,35738260,
35738279,35738397,35738446,35738449,35738502,35738504,35738552,35738604,35738623,35738633,35741999,35742003,35742190,35743029,35743354,35743362,
35743989,35744013,35744036,35745681,35745719,35746052,35746075)
	AND c.roleid = 1 AND c.currency = 20
order by srecommend, username 